if (directMobilePhone === normalizePhone(incoming.currentPhone)) { return { json: { ...incoming, phoneResearchApplied: false, phoneResearchReason: 'same_as_current_phone', phoneResearchConfidence: str(model.confidence) || '', directMobilePhone } }; }
const customFields=[];
if (!str(incoming.apolloPhoneStatus) && !str(incoming.currentCompanyPhone) && str(incoming.currentPhone)) { customFields.push(...customFieldPayload(incoming.companyPhoneFieldId, incoming.currentPhone)); }
const bodyVariants=[{ phone: directMobilePhone, customFields },{ phone: directMobilePhone, customField: Object.fromEntries(customFields.map((f) => [f.id, f.value])) },{ phone: directMobilePhone }];
let updateResult=null;
for(const body of bodyVariants){ const res=await apiRequest.call(this,{method:'PUT',path:`/contacts/${encodeURIComponent(incoming.contactId)}`,body}); if(res.ok){ updateResult={ok:true,bodyUsed:body}; break;} updateResult={ok:false,lastError:res.data,bodyUsed:body}; }
return { json: { ...incoming, phoneResearchApplied:Boolean(updateResult?.ok), phoneResearchReason:str(model.reason) || '', phoneResearchConfidence:str(model.confidence) || '', directMobilePhone, preservedOldPhoneToCompanyPhone:Boolean(!str(incoming.apolloPhoneStatus) && !str(incoming.currentCompanyPhone) && str(incoming.currentPhone)), updateResult } };

const inputs = $input.all().map((i) => i.json || {});
const out = [];
for (const src of inputs) {
  const rowResults = Array.isArray(src.row_results) ? src.row_results : [];
  const sourceRows = Array.isArray(src.source_rows) ? src.source_rows : [];
  const sourceRowById = new Map(sourceRows.map((row) => [String(row.emerald_row_id ?? ''), row]));
  for (const rowResult of rowResults) {
    if (String(rowResult.ghl_contact_sync_status || '').toLowerCase() !== 'synced') continue;
    const sourceRow = sourceRowById.get(String(rowResult.emerald_row_id ?? '')) || {};
    out.push({
      json: {
        company_domain_key: src.company_domain_key,
        company_name: src.company_name,
        rowResult,
        sourceRow,
      }
    });
  }
}
return out;
